CREATE OR REPLACE FUNCTION favorite_validation_own_article(state jsonb, event jsonb) RETURNS text
LANGUAGE plv8 IMMUTABLE AS $validation$
// A reader may not favorite what they wrote. `state.rows.article` is the one
// referenced article, or empty where the reference dangles and the FK will
// refuse after this does.

const verdict = ((state, event) => state.rows.article.every((a) => a.author_id !== event.row.user_id))(state, event);
return verdict === true ? "true" : verdict === false ? "false" : "answered " + typeof verdict;
$validation$;

REVOKE EXECUTE ON FUNCTION favorite_validation_own_article(jsonb, jsonb) FROM PUBLIC;

DROP TRIGGER IF EXISTS favorite_validate ON favorite;

DROP FUNCTION IF EXISTS favorite_validate();

